contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: receiver address and amount to forward to c then ask c to send out that amount.
    // The test deployer will have deployed c with this contract as owner (per problem statement).
    function run(address payable receiver, uint amount, uint fund) public payable {
        require(receiver != address(0));
        require(amount > 0);
        // ensure we have Ether to fund c if desired
        if (fund > 0) {
            require(address(this).balance >= fund);
            // fund the contract c by sending Ether to it
            (bool sent,) = address(c).call{value: fund}("");
            // funding may succeed or fail (but typically succeeds if payable fallback exists via receive)
            // we don't require sent because funding is optional; later logic accounts for c's balance
        }

        // read c balance before the sendTo attempt
        uint beforeC = address(c).balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;

        // General invariant: if the call succeeded (did not revert), then beforeC >= amount and c's balance decreased by amount
        // If the call reverted, no requirement about balances. This asserts that successful send cannot happen when c lacked funds.
        assert(reverted || (beforeC >= amount && beforeC - afterC == amount));
    }

    // allow receiving Ether when funding c
    receive() external payable {}
}

