    // amount and receiver are arbitrary as well; the call is made from this contract
    function run(address attacker, address receiver, uint amount) public payable {
        require(attacker != address(0)); // avoid the zero-address ambiguousness for caller identity
        require(receiver != address(0)); // keep receiver valid to avoid other require failures in sendTo
        require(amount > 0); // ensure positive amount so sendTo would proceed past that check if caller were owner
        // Ensure this contract has enough balance if sendTo would be called (though the non-owner call should revert before transfer)
        require(address(this).balance >= amount);

        // The constructor of C set the owner to the deployer (the checker deploys a fresh C and then deploys this test with that C),
        // and when run() is invoked, msg.sender is some externally owned account. However calls from this contract to c will have
        // msg.sender == address(this). To simulate a non-owner caller, we need to ensure address(this) != owner.
        // We cannot directly read owner (it's private), but we can observe behavior: calling sendTo should revert when not owner.

        // Call sendTo from this contract (which is not the owner in the fresh setup where C was constructed by the checker before passing to this test),
        // and catch whether it reverted.
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if this contract is not the owner then sendTo must revert. We cannot read owner, so we express the rule by
        // checking that either the call reverted or, if it did not revert, then address(this) must be the owner — i.e., only owner can succeed.
        // We detect owner-ness by attempting a second call that would succeed only if this contract is owner: calling sendTo to self with 1 wei.
        // But we must avoid making extra state-changing calls inside the assert. Instead, we use the observed reverted flag and the consequence
        // that a non-reverted call implies this contract is owner. Since we cannot directly prove owner equality, we assert the implication:
        // if the first call did not revert then this contract is able to call sendTo successfully — which can only be true if it is owner.

        // The assertion encodes: reverted == true || true == true (we need a nontrivial relation). We instead assert the invariant:
        // Either the call reverted, or the contract's balance decreased by amount (meaning transfer occurred). This ties success to balance change.
        // Read c's balance after the call.
        uint balAfter = address(c).balance;

        // We need the balance before as well; but reading before must be done prior to the call. So move that logic earlier would be required.
        // However Solidity requires single assert at end. To satisfy that, we restructure: duplicate by redoing flow: we actually must read before before making the call.
    }

    receive() external payable { }
